def solve(facts):
    subtotal = 0
    for line in facts['lines']:
        amount = Decimal(line['qty'] * line['unit_cents']) * (Decimal(100) - Decimal(line['discount_percent'])) / Decimal(100)
        subtotal += int(amount.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    tax = int((Decimal(subtotal) * Decimal(facts['tax_percent']) / Decimal(100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    return {'subtotal_cents': subtotal, 'tax_cents': tax, 'total_cents': subtotal + tax + facts['shipping']}

def check(answer, facts):
    from fractions import Fraction
    subtotal = 0
    for line in facts['lines']:
        discount = Fraction(line['discount_percent'])
        exact = Fraction(line['qty'] * line['unit_cents']) * (100 - discount) / 100
        subtotal += (2 * exact.numerator + exact.denominator) // (2 * exact.denominator)
    tax_exact = Fraction(subtotal) * Fraction(facts['tax_percent']) / 100
    tax = (2 * tax_exact.numerator + tax_exact.denominator) // (2 * tax_exact.denominator)
    return answer == {'subtotal_cents': subtotal, 'tax_cents': tax, 'total_cents': subtotal + tax + facts['shipping']}"}

